        except pytz.UnknownTimeZoneError:
            raise ValueError("tz must be a valid time zone")

    time = datetime.time(nanoseconds // 1000000000, (nanoseconds // 1000000) % 1000, (nanoseconds // 1000) % 1000)
    if tz is not None:
        time = time.replace(tzinfo=tz)
    return time

