def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    Args:
        nanoseconds (int): The number of nanoseconds since midnight.
        tz (optional): The time zone as a string.

    Returns:
        Time: The hydrated time value.

    Raises:
        ValueError: If the input data is not valid.
        OverflowError: If the input data is too large to convert to a time value.
    """
    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer value")
    if tz is not None and not isinstance(tz, str):
        raise ValueError("tz must be a string value")

    try:
        if tz is not None:
            time = Time.fromtimestamp(nanoseconds / 1e9, tz=tz)
        else:
            time = Time.fromtimestamp(nanoseconds / 1e9)
    except OverflowError as e:
        raise ValueError("Input data is too large to convert to a time value") from e

    return time

