def protocol_handlers(cls, protocol_version=None):
    handlers = {
        (3, 5): Bolt35ProtocolHandler,
        (4, 0): Bolt40ProtocolHandler,
        (4, 1): Bolt41ProtocolHandler,
        (4, 2): Bolt42ProtocolHandler,
        (4, 3): Bolt43ProtocolHandler
    }
    if protocol_version is not None:
        if not isinstance(protocol_version, (list, tuple)):
            raise TypeError(f"Protocol version must be a tuple or list, got {type(protocol_version)}")
        elif len(protocol_version) != 2:
            raise ValueError(f"Protocol version must have exactly two elements, got {len(protocol_version)}")
        elif not isinstance(protocol_version[0], int) or not isinstance(protocol_version[1], int):
            raise ValueError(f"Protocol version must contain two integer values, got {type(protocol_version[0])} and {type(protocol_version[1])}")
        return {protocol_version: handlers[protocol_version]}
    return handlers
