def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Args:
        orderings (list[list]): Multiple orderings to be merged. Each ordering is a list of objects.

    Returns:
        list: The merged ordering.

    Raises:
        ValueError: If the input orderings do not contain the same objects in the same order.
        ValueError: If an object appears in two or more orderings, but the suffixes do not match.

    Examples:
        _mergeOrderings([
            ['x', 'y', 'z'],
            ['q', 'z'],
            [1, 3, 5],
            ['z']
        ])
        # Output: ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    # Step 1: Flatten the input orderings and remove duplicates
    all_items = set()
    for ordering in orderings:
        all_items.update(ordering)
    all_items = list(all_items)

    # Step 2: Create a mapping from objects to their relative positions in the merged ordering
    obj_index = {}
    for i, obj in enumerate(all_items):
        obj_index[obj] = i

    # Step 3: Create the merged ordering
    merged_ordering = []
    for ordering in orderings:
        for obj in ordering:
            if obj not in merged_ordering:
                merged_ordering.append(obj)

    # Step 4: Check for any zero-padding
    zero_padding = []
    for i in range(len(merged_ordering) - 1):
        if merged_ordering[i] is not None and merged_ordering[i + 1] is not None:
            if obj_index[merged_ordering[i]] < obj_index[merged_ordering[i + 1]]:
                break
        else:
            zero_padding.append(i)

    # Step 5: Fill in the zero-padding if necessary
    if zero_padding:
        for i in zero_padding:
            merged_ordering[i] = None

    return merged_ordering

