        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if validate_objects:
        # Iterate over all objects in the storage root and validate them
        for object_hash in self.root_hashes:
            try:
                data = self.get_object(object_hash)
                good_objects += 1
            except KeyError:
                # If the object is not found, it is not a valid object
                pass
            num_objects += 1

        if num_objects == 0:
