def generate_version_inventory(self, version_dirs):
    """Returns a version inventory for the given version directory names.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    inventory = {
        'digests': set(),
        'files': set(),
    }

    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.json')
        with open(inventory_file, 'r') as f:
            version_inventory = json.load(f)

        for digest in version_inventory['digests']:
            inventory['digests'].add(digest)

        for file_path in version_inventory['files']:
            inventory['files'].add(file_path)

    return inventory

def validate_version_tags(self, version_dirs):
    """Raises an exception if any version tag is missing or invalid."""
    for version_dir in version_dirs:
        if version_dir not in self.content_dir:
            raise Exception(f'Version directory {version_dir} not found')

    for version_dir in version_dirs:
        version_tag_file = os.path.join(version_dir, 'version_tag')
        with open(version_tag_file, 'r') as f:
            version_tag = f.read().strip()

        if not re.match(r'^v\d+\.\d+\.\d+$', version_tag):
            raise Exception(f'Invalid version tag {version_tag}')

    return True

def validate_change_logs(self, version_dirs):
    """Raises an exception if any change log is missing or invalid."""
    for version_dir in version_dirs:
        change_log_file = os.path.join(version_dir, 'changelog.md')
        if not os.path.isfile(change_log_file):
            raise Exception(f'Change log file {change_log_file} not found')

        change_log = open(change_log_file, 'r').read()
        if not re.match(r'^## Version \d+\.\d+\.\d+$', change_log):
            raise Exception(f'Invalid change log file {change_log_file}')

    return True

def validate_files(self, version_dirs):
    """Raises an exception if any file is missing or invalid."""
    for version_dir in version_dirs:
        files_dir = os.path.join(version_dir, 'files')
        if not os.path.isdir(files_dir):
            raise Exception(f'Missing files directory {files_dir}')

        for root, dirs, files in os.walk(files_dir):
            for file in files:
                file_path = os.path.join(root, file)
                if not os.path.isfile(file_path):
                    raise Exception(f'File {file_path} is not a file')

    return True
