def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :raises: ``ValueError`` if the histogram's scale is already 0 and
        one tries to rescale it.
    """
    if other is None:
        if hasattr(self, "_scale"):
            return self._scale
        else:
            return self.compute_scale()
    if not is_bin_counts(self.bins):
        raise ValueError("Invalid bin_counts argument")
    if other < 0:
        raise ValueError("Negative scale value")
    if self._scale == 0:
        if other == 0:
            raise ValueError("Cannot rescale histogram with scale 0")
        self._rescale_bins(other)
        self._scale = other
        self._bins = other * self._bins
    else:
        self._scale = self._scale * other
        self._rescale_bins(self._scale)
    if recompute:
        self._scale = None
        self.compute_scale()

def _rescale_bins(self, scale):
    if not is_bin_counts(self.bins):
        raise ValueError("Invalid bin_counts argument")
    self._bins = np.array(self._bins)
    self._bins = self._bins * scale

def compute_scale(self):
    if not hasattr(self, "_bins"):
        raise ValueError("Cannot compute scale without bin_counts")
    self._scale = np.sum(self._bins)

