def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """

    if other is not None:
        if self.scale is None or self.scale <= 0:
            raise LenaValueError("Cannot rescale graph with unknown or zero scale")
        if other <= 0:
            raise LenaValueError("Cannot set scale to a non-positive value")

        self.scale = other
        self._rescale()

    return self.scale

def _rescale(self):
    coordinate = self.node.coordinate
    errors = []

    for node in self.nodes:
        if node.coordinate == coordinate:
            node.coordinate = node.coordinate * self.scale
        else:
            errors.append(node.coordinate * self.scale)

    for error in errors:
        if error.coordinate == coordinate:
            error.coordinate = error.coordinate * self.scale

    self.node.coordinate = coordinate * self.scale

def scale(self, other=None):
    if other is None:
        return self._scale
    if isinstance(other, numbers.Number):
        if self._scale == 0 or self._scale is None:
            raise LenaValueError("Cannot rescale graph with unknown or zero scale")
        for i in range(len(self.fields)):
            field = self.fields[i]
            for coordinate in field.coordinates:
                coordinate *= other / self._scale
        self._scale = other
    else:
        raise TypeError("other must be a number")

