def _verifyCallable(method, cand_method):
    # Check the method signature
    sig = inspect.signature(method)
    csig = inspect.signature(cand_method)

    # Make sure the candidate method has the same number of arguments
    if len(sig.parameters) != len(csig.parameters):
        return False

    # Make sure the candidate method has the same argument names
    if set(sig.parameters.keys()) != set(csig.parameters.keys()):
        return False

    # Make sure the candidate method has the same return type
    if sig.return_annotation != csig.return_annotation:
        return False

    return True

