def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from lxml import etree

    try:
        # Try to parse the document as JSON
        webfinger = json.loads(document)
        return webfinger
    except ValueError:
        # If it's not JSON, try parsing it as XRD
        root = etree.fromstring(document)
        webfinger = {}
        for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
            rel = link.get('rel')
            if rel:
                webfinger[rel] = link.get('href')
        return webfinger
    except Exception as e:
        raise ValueError(f"Invalid Diaspora webfinger document: {e}")

