def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The parser dictionary containing the include directive.

    Returns:
        dict: The resolved include directive.

    Raises:
        ValueError: If the include directive is not valid.
        KeyError: If the include key is not found in the parser dictionary.

    """
    try:
        include_dict = parser_dict["includes"]
        resolved_includes = {}
        for key, value in include_dict.items():
            if isinstance(value, list):
                resolved_includes[key] = [self._resolve_include(v) for v in value]
            else:
                resolved_includes[key] = self._resolve_include(value)
        return resolved_includes
    except KeyError:
        raise ValueError("Include key not found in parser dictionary") from None

def _resolve_include(self, include_dict):
    """Resolves a single include entry in the spec files.

    Args:
        include_dict (dict): The include dictionary containing the include directive.

    Returns:
        dict: The resolved include entry.

    Raises:
        ValueError: If the include entry is not valid.

    """
    try:
        include_key = include_dict["key"]
        include_value = include_dict["value"]
        if include_key not in self._valid_includes:
            raise ValueError(f"Invalid include key: {include_key}")
        resolved_include = self._include_mappings[include_key](include_value)
        return {include_key: resolved_include}
    except KeyError:
        raise ValueError("Include key or value not found in include dictionary") from None

